<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import ApiOfficeView from './ApiOfficeView.vue'
import AppModal from '@/components/AppModal.vue'
import AppIcon from '@/components/AppIcon.vue'
import ModuleDemoContext from '@/components/ModuleDemoContext.vue'
import { demoMode } from '@/services/quality'
import { currentOffice, companyMode, supportState, assignmentLabels, decideAssignment, event, persist, uid, type Assignment } from '@/services/supportDemo'
const route=useRoute()
const section=computed(()=>route.path.endsWith('accompagnateurs')?'access':route.path.endsWith('profil')?'profile':'office')
const title=computed(()=>section.value==='access'?'Accompagnateurs':section.value==='profile'?'Mon profil & rôle':'Mon officine')
const tab=ref('Informations générales');const edit=ref(false);const detail=ref(false);const decision=ref(false);const proposal=ref(false);const error=ref('');const message=ref('');const reason=ref('');const selected=ref<Assignment|null>(null);const outcome=ref<'approved'|'refused'|'revoked'>('approved')
const form=ref({...currentOffice.value});const proposed=ref({name:'',function:'Accompagnateur',scope:'Accompagnement qualité',start:'',end:''})
const events=computed(()=>supportState.events.filter(e=>e.officeId===currentOffice.value.id))
watch(()=>currentOffice.value.id,()=>{edit.value=false;detail.value=false;decision.value=false;proposal.value=false;selected.value=null;message.value=''})
function editOffice(){form.value={...currentOffice.value};error.value='';edit.value=true}
function save(){try{if(!form.value.name.trim()||!form.value.city.trim()||!form.value.contact.trim()||!form.value.phone.trim())throw new Error('Nom, commune, contact et téléphone requis.');Object.assign(currentOffice.value,{name:form.value.name,city:form.value.city,department:form.value.department,address:form.value.address,phone:form.value.phone,email:form.value.email,contact:form.value.contact});event(currentOffice.value.id,currentOffice.value.id,'Fiche officine modifiée');persist();edit.value=false;message.value='Fiche fictive enregistrée.'}catch(e){error.value=(e as Error).message}}
function decide(a:Assignment,status:typeof outcome.value){selected.value=a;outcome.value=status;reason.value='';error.value='';decision.value=true}
function confirm(){try{decideAssignment(selected.value!.id,outcome.value,reason.value);decision.value=false;detail.value=false;message.value='Décision enregistrée dans la simulation.'}catch(e){error.value=(e as Error).message}}
function propose(){try{const p=proposed.value;if(!p.name.trim()||!p.start||!p.end||p.end<p.start)throw new Error('Complétez le nom et une période valide.');const id=uid('ACC');currentOffice.value.assignments.push({...p,id,status:'pending',reason:''});event(currentOffice.value.id,id,'Accompagnateur proposé — accès non ouvert');persist();proposal.value=false;message.value='Proposition créée. Passez en vue officine pour décider.'}catch(e){error.value=(e as Error).message}}
</script>
<template><section class="page erp-page"><div class="page-heading compact"><div><p class="eyebrow">MODULE 01 · OFFICINES & ACCÈS</p><h1>{{title}}</h1><p class="page-subtitle">Un espace identifié, des accès choisis et un historique conservé.</p></div><span class="module-chip">M01</span></div>
<ApiOfficeView v-if="!demoMode"/><template v-else><ModuleDemoContext/><p v-if="message" class="alert success" role="status">{{message}}</p>
<div v-if="section==='profile'" class="panel"><div class="panel-heading"><div class="identity-row"><span class="large-avatar">AD</span><div><h2>Alex Démo</h2><p class="page-subtitle">alex@example.test · Identité fictive</p></div></div><span class="status-badge active">Compte de démonstration</span></div><div class="form-body"><dl class="application-summary"><dt>Rôle simulé</dt><dd>{{companyMode?'Coordinateur de l’entreprise':'Administrateur officine'}}</dd><dt>Officine sélectionnée</dt><dd>{{currentOffice.name}}</dd><dt>Fonction métier</dt><dd>Responsable de démonstration — distinct du rôle applicatif</dd><dt>Permissions</dt><dd>Les droits affichés ici sont simulés. Les rôles et accès réels restent contrôlés par Laravel.</dd></dl><div class="module-links"><RouterLink to="/equipe" class="button secondary">Équipe, accès & rôles</RouterLink><RouterLink to="/application" class="button secondary">Mon dossier d’ouverture</RouterLink></div><p class="module-disclaimer">Email vérifié, Google et MFA : non livrés dans cette tranche. Aucun bouton ne simule leur activation.</p></div></div>
<template v-else-if="section==='office'"><div class="panel"><div class="panel-heading"><div class="identity-row"><span class="large-avatar"><AppIcon name="plus" :size="26"/></span><div><h2>{{currentOffice.name}}</h2><p class="page-subtitle">{{currentOffice.code}} · {{currentOffice.city}}, Bénin</p></div></div><button v-if="!companyMode" class="button primary" @click="editOffice"><AppIcon name="settings" :size="15"/>Modifier la fiche</button></div><div class="erp-tabs"><button v-for="t in ['Informations générales','Contacts','Équipe et accès','Accompagnateurs','Historique']" :key="t" :class="{selected:tab===t}" @click="tab=t">{{t}}</button></div>
<div class="form-body" v-if="tab==='Informations générales'"><dl class="application-summary"><dt>Nom de l’officine</dt><dd>{{currentOffice.name}}</dd><dt>Code</dt><dd>{{currentOffice.code}}</dd><dt>État SaaS</dt><dd><span class="status-badge" :class="currentOffice.status">{{currentOffice.status==='active'?'Active':'En attente'}}</span> — ne vaut pas autorisation réglementaire</dd><dt>Département / commune</dt><dd>{{currentOffice.department}} / {{currentOffice.city}}</dd><dt>Adresse descriptive</dt><dd>{{currentOffice.address}}</dd><dt>Pays</dt><dd>Bénin</dd></dl></div>
<div v-else-if="tab==='Contacts'" class="form-body"><dl class="application-summary"><dt>Contact principal</dt><dd>{{currentOffice.contact}}</dd><dt>Téléphone</dt><dd>{{currentOffice.phone}}</dd><dt>Email</dt><dd>{{currentOffice.email}}</dd></dl><p class="module-disclaimer">Un contact n’est pas automatiquement un compte utilisateur.</p></div>
<div v-else-if="tab==='Équipe et accès'" class="form-body"><h3>Rôles locaux, invitations et membres</h3><p class="page-subtitle">L’espace Équipe existant permet d’inviter un membre, de cocher ses rôles et de gérer les accès en modale. Sa démo est indépendante des officines de ce nouveau jeu d’exemples.</p><RouterLink to="/equipe" class="button primary">Accéder à l’équipe de démonstration</RouterLink></div>
<div v-else-if="tab==='Accompagnateurs'" class="form-body"><h3>{{currentOffice.assignments.filter(a=>a.status==='approved').length}} accès approuvé(s)</h3><p class="page-subtitle">Chaque proposition nécessite une décision explicite de l’officine.</p><RouterLink to="/dashboard/accompagnateurs" class="button secondary">Consulter les accompagnateurs</RouterLink></div>
<div v-else class="form-body"><ol class="event-list"><li v-for="e in events" :key="e.id"><span class="event-dot"></span><div><strong>{{e.title}}</strong><small>{{e.date.slice(0,10)}} · {{e.actor}}</small></div></li></ol><p v-if="!events.length" class="empty-state">Aucun événement dans cette simulation.</p></div></div></template>
<template v-else><div class="stats-grid"><div class="stat-card"><span class="stat-top">Accès approuvés <AppIcon name="check"/></span><strong>{{currentOffice.assignments.filter(a=>a.status==='approved').length}}</strong><span class="stat-note">La période et la portée restent à vérifier à l’accès</span></div><div class="stat-card"><span class="stat-top">À approuver <AppIcon name="clock"/></span><strong>{{currentOffice.assignments.filter(a=>a.status==='pending').length}}</strong><span class="stat-note">Aucun accès avant votre accord</span></div><div class="stat-card"><span class="stat-top">Votre espace <AppIcon name="quality"/></span><strong class="stat-text">Votre décision</strong><span class="stat-note">Une mission n’ouvre pas d’accès à elle seule</span></div></div><div class="panel"><div class="panel-heading"><div><h2>Affectations des accompagnateurs</h2><p class="page-subtitle">Portée, période et approbation explicites.</p></div><button v-if="companyMode" class="button primary" @click="proposal=true;error=''"><AppIcon name="plus" :size="15"/>Proposer un accompagnateur</button></div><div class="table-scroll"><table><thead><tr><th>ACCOMPAGNATEUR</th><th>PÉRIMÈTRE</th><th>PÉRIODE</th><th>STATUT</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="a in currentOffice.assignments" :key="a.id"><td><button class="table-title" @click="selected=a;detail=true">{{a.name}}</button><span class="table-subtitle">{{a.function}}</span></td><td>{{a.scope}}</td><td>{{a.start}} → {{a.end}}</td><td><span class="status-badge" :class="a.status">{{assignmentLabels[a.status]}}</span></td><td><button class="button secondary small" @click="selected=a;detail=true">Ouvrir</button></td></tr><tr v-if="!currentOffice.assignments.length"><td colspan="5" class="empty-state">Aucun accompagnateur proposé pour cette officine.</td></tr></tbody></table></div><div class="panel-foot">Les autorisations restent propres à chaque officine.</div></div></template>
<AppModal v-model="edit" title="Modifier la fiche officine" size="wide"><form id="office-form" class="form-body form-grid" @submit.prevent="save"><p v-if="error" class="alert error" role="alert">{{error}}</p><label>Nom<input v-model="form.name" required maxlength="150"/></label><label>Contact principal<input v-model="form.contact" required maxlength="100"/></label><label>Commune<input v-model="form.city" required/></label><label>Département<input v-model="form.department"/></label><label>Téléphone<input v-model="form.phone" required/></label><label>Email<input v-model="form.email" type="email"/></label><label class="span-2">Adresse descriptive<textarea v-model="form.address" rows="3"/></label></form><template #footer><button class="button secondary" @click="edit=false">Annuler</button><button class="button primary" type="submit" form="office-form">Enregistrer</button></template></AppModal>
<AppModal v-model="detail" title="Accès de l’accompagnateur"><div v-if="selected" class="form-body"><dl class="application-summary"><dt>Accompagnateur</dt><dd>{{selected.name}}</dd><dt>Fonction</dt><dd>{{selected.function}}</dd><dt>Portée</dt><dd>{{selected.scope}}</dd><dt>Période</dt><dd>{{selected.start}} → {{selected.end}}</dd><dt>État</dt><dd>{{assignmentLabels[selected.status]}}</dd><dt v-if="selected.reason">Motif</dt><dd v-if="selected.reason">{{selected.reason}}</dd></dl><p class="module-disclaimer">Modifier la portée ou la période nécessiterait une nouvelle approbation ; aucun accès implicite.</p></div><template #footer><button class="button secondary" @click="detail=false">Fermer</button><template v-if="selected && !companyMode"><template v-if="selected.status==='pending'"><button class="button secondary" @click="decide(selected,'refused')">Refuser</button><button class="button primary" @click="decide(selected,'approved')">Approuver l’accès</button></template><button v-if="selected.status==='approved'" class="button danger" @click="decide(selected,'revoked')">Retirer l’accès</button></template></template></AppModal>
<AppModal v-model="decision" :title="outcome==='approved'?'Approuver cet accès ?':outcome==='refused'?'Refuser cet accès ?':'Retirer cet accès ?'" size="small"><form id="decision-form" class="form-body" @submit.prevent="confirm"><p v-if="error" class="alert error" role="alert">{{error}}</p><p>{{selected?.name}} · {{selected?.scope}}</p><label v-if="outcome!=='approved'">Motif<textarea v-model="reason" required rows="3"/></label><p v-else>Vous autorisez cet accompagnateur sur la portée et la période affichées, dans la simulation uniquement.</p></form><template #footer><button class="button secondary" @click="decision=false">Annuler</button><button class="button primary" form="decision-form" type="submit">Confirmer la décision</button></template></AppModal>
<AppModal v-model="proposal" title="Proposer un accompagnateur"><form id="proposal-form" class="form-body form-grid" @submit.prevent="propose"><p v-if="error" class="alert error" role="alert">{{error}}</p><label>Nom fictif<input v-model="proposed.name" required/></label><label>Fonction<input v-model="proposed.function" required/></label><label class="span-2">Périmètre<select v-model="proposed.scope"><option>Accompagnement qualité</option><option>Organisation et procédures</option></select></label><label>Début<input v-model="proposed.start" type="date" required/></label><label>Fin<input v-model="proposed.end" type="date" :min="proposed.start" required/></label><p class="module-disclaimer span-2">La proposition n’ouvre aucun droit. L’officine doit l’approuver.</p></form><template #footer><button class="button secondary" @click="proposal=false">Annuler</button><button class="button primary" form="proposal-form" type="submit">Envoyer la proposition fictive</button></template></AppModal>
</template></section></template>
